// Generated by scripts/build-glossary-data.mjs from content-source/glossary. Do not edit by hand.
export const GLOSSARY_SHARD = Object.freeze({"bitcoin":{"slug":"bitcoin","cat":"basics","en":"Bitcoin (BTC)","contentLocale":"es","term":"Bitcoin (BTC)","aka":["BTC","bitcóin"],"short":"Bitcoin (BTC) es la primera criptomoneda, lanzada en 2009, con un suministro máximo de 21 millones de unidades y una red descentralizada que funciona con prueba de trabajo.","body":[["Bitcoin fue creado por una persona o grupo bajo el seudónimo ",["Satoshi","satoshi"]," Nakamoto. Su red registra todas las transacciones en una ",["blockchain","blockchain"]," pública y los mineros compiten con potencia de cálculo para añadir cada nuevo bloque, cobrando a cambio la recompensa de bloque y las comisiones."],"Su rasgo más citado es la escasez: nunca existirán más de 21 millones de BTC. Cada unos cuatro años ocurre el halving, que reduce a la mitad la emisión nueva; el de abril de 2024 dejó la recompensa en 3,125 BTC por bloque. Además, 1 BTC se divide en 100.000.000 satoshis, así que puedes comprar fracciones pequeñas.","Hoy puedes comprar bitcoin en exchanges, guardarlo en una wallet propia o, en algunos mercados, exponerte a él mediante ETF spot, que empezaron a cotizar en Estados Unidos en enero de 2024. Su precio es volátil, así que el tamaño de tu posición importa más que el momento exacto de entrada."],"example":["Supón que BTC cotiza a 80.000 ",["USDT","usdt"]," y quieres invertir 100 USDT. Recibirías 0,00125 BTC, es decir, 125.000 satoshis (antes de comisiones). Si pagas una comisión de 0,1 %, se descuentan 0,1 USDT y recibes unos 124.875 sats. Si BTC sube a 88.000 USDT, esa cantidad pasa a valer unos 109,9 USDT; si baja a 72.000, unos 89,9 USDT."],"mistakes":["Pensar que necesitas comprar un bitcoin entero cuando puedes comprar una fracción.","Retirar BTC por una red no compatible con la dirección de destino, por ejemplo confundir la red Bitcoin con un token envuelto en otra cadena.","Tomar el halving como garantía de subida de precio."],"faq":[{"q":"¿Cuántos bitcoins existen?","a":"El protocolo limita el suministro a 21 millones de BTC. La mayoría ya se ha minado y el resto se emite cada vez más despacio gracias a los halvings."},{"q":"¿Puedo comprar menos de 1 bitcoin?","a":"Sí. Bitcoin se divide en 100 millones de satoshis, así que puedes comprar por el importe que quieras, respetando el mínimo de tu exchange."},{"q":"¿Quién creó Bitcoin?","a":"Lo creó Satoshi Nakamoto, un seudónimo cuya identidad real sigue sin confirmarse. El documento técnico se publicó en 2008 y la red arrancó en 2009."}],"title":"¿Qué es Bitcoin (BTC)? Significado y cómo funciona","description":"Qué es Bitcoin, por qué su suministro está limitado a 21 millones, cómo funcionan el halving y los satoshis, y cómo comprar una fracción.","related":[["satoshi","Satoshi (sats)","Un satoshi (sat) es la unidad más pequeña de bitcoin: 1 BTC equivale a 100.000.000 satoshis, y el nombre rinde homenaje a Satoshi Nakamoto, el creador de Bitcoin."],["bitcoin-halving","Halving de Bitcoin","El halving de Bitcoin es el evento programado en el protocolo que, cada 210.000 bloques (unos cuatro años), reduce a la mitad la recompensa que reciben los mineros por cada bloque nuevo."],["proof-of-work","Prueba de trabajo (proof of work, PoW)","La prueba de trabajo (PoW) es un mecanismo de consenso en el que los mineros gastan potencia de cálculo y electricidad para resolver un problema criptográfico y ganar el derecho a añadir el siguiente bloque."],["mining","Minería de criptomonedas","La minería de criptomonedas es el proceso por el que equipos especializados aportan potencia de cálculo a una red de prueba de trabajo para validar transacciones, crear nuevos bloques y cobrar la recompensa en monedas nuevas y comisiones."],["spot-bitcoin-etf","ETF de bitcoin al contado (spot)","Un ETF de bitcoin al contado es un fondo que cotiza en bolsa y compra y guarda bitcoin real, de modo que sus participaciones siguen el precio de BTC sin que tengas que custodiarlo tú."]],"lesson":{"id":"E01","slug":"can-i-buy-part-of-a-bitcoin","ep":1,"title":"Un bitcoin cuesta tanto. ¿Aún puedo comprar algo?"},"coin":{"slug":"bitcoin","name":"Bitcoin","symbol":"BTC"},"tool":null,"cta":true},"proof-of-work":{"slug":"proof-of-work","cat":"basics","en":"Proof of work (PoW)","contentLocale":"es","term":"Prueba de trabajo (proof of work, PoW)","aka":["PoW","proof of work"],"short":"La prueba de trabajo (PoW) es un mecanismo de consenso en el que los mineros gastan potencia de cálculo y electricidad para resolver un problema criptográfico y ganar el derecho a añadir el siguiente bloque.","body":["Los mineros prueban millones de combinaciones por segundo hasta encontrar un hash que cumpla la dificultad exigida por la red. Quien lo encuentra primero publica el bloque y cobra la recompensa más las comisiones. El resto de nodos comprueba la solución en un instante.",["La seguridad viene del coste. Para reescribir el historial, un atacante necesitaría controlar más potencia de cálculo que el resto de la red junta, lo que se conoce como ataque del 51 %. En una red grande como ",["Bitcoin","bitcoin"]," eso exige una inversión enorme en hardware y energía."],["La red ajusta la dificultad periódicamente para que los bloques salgan a un ritmo estable. El principal debate en torno a PoW es su consumo energético. ",["Ethereum","ethereum"]," la abandonó en 2022 por la ",["prueba de participación","proof-of-stake"],"; Bitcoin, Litecoin y Dogecoin siguen usándola."]],"example":"Bitcoin busca un bloque cada 10 minutos y revisa la dificultad cada 2.016 bloques, unas dos semanas. Supón que entra mucha potencia nueva y esos 2.016 bloques salen en 12 días en lugar de 14. La red sube la dificultad en proporción (14 / 12, alrededor de un 17 %) para volver a unos 10 minutos por bloque. Si muchos mineros se apagan y el periodo dura 16 días, la dificultad baja.","mistakes":["Pensar que minar es resolver cálculos útiles; en realidad es un sorteo basado en fuerza bruta.","Creer que más mineros significa transacciones más rápidas; el tiempo de bloque se mantiene estable por diseño.","Suponer que cualquier red PoW pequeña es tan segura como Bitcoin."],"faq":[{"q":"¿Qué criptomonedas usan prueba de trabajo?","a":"Bitcoin es la más conocida. También usan PoW Litecoin, Dogecoin, Bitcoin Cash y Monero, entre otras."},{"q":"¿Qué diferencia hay entre PoW y PoS?","a":"En PoW la seguridad depende de potencia de cálculo y energía; en PoS, de monedas bloqueadas como garantía. PoS consume mucha menos energía, pero cambia el modelo de incentivos."}],"title":"¿Qué es la prueba de trabajo (PoW)? Significado","description":"Qué es la prueba de trabajo, cómo compiten los mineros por cada bloque, cómo se ajusta la dificultad y en qué se diferencia de PoS.","related":[["mining","Minería de criptomonedas","La minería de criptomonedas es el proceso por el que equipos especializados aportan potencia de cálculo a una red de prueba de trabajo para validar transacciones, crear nuevos bloques y cobrar la recompensa en monedas nuevas y comisiones."],["hash-rate","Tasa de hash (hash rate)","La tasa de hash es la potencia de cálculo total que los mineros dedican a una red de prueba de trabajo, medida en hashes por segundo, como Bitcoin en EH/s."],["proof-of-stake","Prueba de participación (proof of stake, PoS)","La prueba de participación (PoS) es un mecanismo de consenso en el que los validadores bloquean monedas como garantía para proponer y confirmar bloques, y pueden perder parte de ellas si actúan de forma deshonesta."],["blockchain","Blockchain (cadena de bloques)","Una blockchain o cadena de bloques es un registro digital compartido en el que las transacciones se agrupan en bloques encadenados entre sí, de modo que cambiar un dato antiguo exigiría rehacer todos los bloques posteriores."],["bitcoin-halving","Halving de Bitcoin","El halving de Bitcoin es el evento programado en el protocolo que, cada 210.000 bloques (unos cuatro años), reduce a la mitad la recompensa que reciben los mineros por cada bloque nuevo."]],"lesson":null,"coin":{"slug":"bitcoin","name":"Bitcoin","symbol":"BTC"},"tool":null,"cta":false},"token-unlock":{"slug":"token-unlock","cat":"basics","en":"Token unlock","contentLocale":"es","term":"Desbloqueo de tokens (token unlock)","aka":["token unlock","desbloqueo","unlock","vesting"],"short":"Un desbloqueo de tokens (token unlock) es el momento en que tokens que estaban bloqueados por un calendario de vesting pasan a estar disponibles para sus dueños, normalmente equipo, inversores o tesorería, y pueden venderse.","body":["Cuando un proyecto lanza su token, una gran parte suele estar sujeta a vesting: un periodo inicial sin liberar (cliff) seguido de liberaciones periódicas, mensuales o diarias. El objetivo es alinear al equipo y a los inversores con el proyecto a largo plazo.",["Los desbloqueos aumentan el ",["suministro circulante","circulating-supply"],". Si quienes reciben los tokens los compraron muy barato, pueden querer vender parte, lo que añade presión vendedora. Por eso muchos traders siguen los calendarios de desbloqueo de los tokens que tienen."],"El efecto real no es automático. Depende del tamaño del desbloqueo respecto al circulante, de quién lo recibe y de la demanda en ese momento. Un desbloqueo para recompensas de comunidad no se comporta igual que uno para fondos de capital riesgo."],"example":["Supón que un token tiene 300 millones de unidades circulando y cotiza a 2 ",["USDT","usdt"],". El próximo mes se desbloquean 45 millones para inversores iniciales, que compraron a 0,20 USDT. Eso equivale a un 15 % más de suministro. Al precio actual, ese lote vale 90 millones de USDT; aunque el precio cayera a la mitad, esos inversores seguirían ganando cinco veces lo invertido, así que tienen margen para vender."],"mistakes":["Comprar justo antes de un desbloqueo grande sin haber revisado el calendario.","Suponer que todos los tokens desbloqueados se venderán de inmediato.","Confundir el desbloqueo con la emisión de tokens nuevos."],"faq":[{"q":"¿Un desbloqueo de tokens siempre baja el precio?","a":"No siempre. Aumenta la oferta disponible, pero el impacto depende del tamaño, de quién recibe los tokens y de la demanda. El mercado a veces ya lo descuenta antes."},{"q":"¿Qué es el vesting?","a":"Es el calendario que define cuándo y cuántos tokens bloqueados se liberan. Suele incluir un cliff inicial y luego liberaciones periódicas."}],"title":"¿Qué es un desbloqueo de tokens (token unlock)?","description":"Qué es un desbloqueo de tokens, cómo funciona el vesting y por qué los unlocks grandes pueden presionar el precio de un token.","related":[["tokenomics","Tokenomics (tokenomía)","Tokenomics es el diseño económico de un token: cuántos existen, cómo se reparten, cuándo se liberan, para qué se usan y qué mecanismos aumentan o reducen su suministro."],["circulating-supply","Suministro circulante (circulating supply)","El suministro circulante es la cantidad de unidades de una criptomoneda que ya están disponibles y pueden negociarse en el mercado, sin contar las bloqueadas, reservadas o quemadas."],["fully-diluted-valuation","Valoración totalmente diluida (FDV)","La valoración totalmente diluida (FDV) es el precio actual de un token multiplicado por su suministro máximo o total, es decir, lo que valdría el proyecto si todos los tokens ya estuvieran en circulación."],["airdrop","Airdrop","Un airdrop es una distribución gratuita de tokens que un proyecto envía a ciertas direcciones, normalmente para recompensar a usuarios tempranos, repartir la gobernanza o promocionar un lanzamiento."]],"lesson":null,"coin":null,"tool":"/coins","cta":false},"limit-order":{"slug":"limit-order","cat":"trading","en":"Limit order","contentLocale":"es","term":"Orden límite (limit order)","aka":["limit order","orden limitada"],"short":"Una orden límite (limit order) es una instrucción para comprar o vender a un precio concreto o mejor: una compra límite solo se ejecuta a ese precio o por debajo, y una venta límite, a ese precio o por encima.","body":["Con una orden límite controlas el precio, pero no la ejecución. Si el mercado no llega a tu precio, la orden se queda en el libro esperando. Si llega, puede ejecutarse completa o en parte, según la cantidad disponible.","Cuando tu orden límite queda en el libro y otro la ejecuta después, actúas como maker y sueles pagar la comisión más baja. Si pones una compra límite por encima del precio de venta actual, se ejecuta al instante y pagas como taker, aunque nunca por encima de tu límite.",["Las órdenes límite son la base de muchas estrategias: comprar en soportes, escalonar entradas, tomar beneficios. Su duración depende de la configuración: por defecto suelen permanecer activas hasta que las canceles (",["GTC","time-in-force"],"), pero puedes elegir otras ",["opciones","options"],"."]],"example":["Supón que ",["BTC","bitcoin"]," cotiza a 62.400 ",["USDT","usdt"]," y colocas una compra límite de 0,02 BTC a 61.000. Si el precio no baja de 61.500, tu orden nunca se ejecuta. Si baja a 60.800, tu orden se llena a 61.000 o mejor: pagas 1.220 USDT. Con una ",["comisión maker","maker-taker-fees"]," ilustrativa de 0,08 %, pagas 0,98 USDT de comisión, frente a 1,22 USDT si la comisión taker fuera de 0,1 %."],"mistakes":["Colocar la orden y olvidarla, y que se ejecute semanas después cuando ya no la querías.","Poner una compra límite por encima del precio actual pensando que esperará.","Fijar precios tan lejos que la orden nunca se ejecuta y pierdes el movimiento."],"faq":[{"q":"¿Una orden límite garantiza la ejecución?","a":"No. Garantiza el precio máximo o mínimo, pero si el mercado no llega a él o no hay suficiente cantidad, puede no ejecutarse o hacerlo solo en parte."},{"q":"¿Las órdenes límite pagan menos comisión?","a":"Si quedan en el libro y se ejecutan después, sí: pagan la comisión maker, que suele ser más baja. Si se ejecutan al instante, pagan como taker."}],"title":"¿Qué es una orden límite (limit order) en cripto?","description":"Qué es una orden límite, cómo fija tu precio de compra o venta, cuándo pagas comisión maker y por qué no garantiza la ejecución.","related":[["market-order","Orden de mercado (market order)","Una orden de mercado (market order) es una instrucción para comprar o vender de inmediato al mejor precio disponible en el libro de órdenes, priorizando la rapidez de ejecución sobre el precio exacto."],["post-only-order","Orden post-only (solo maker)","Una orden post-only es una orden límite que solo se acepta si queda en el libro de órdenes como maker; si se fuera a ejecutar al instante contra una orden existente, el exchange la cancela o la rechaza."],["time-in-force","Vigencia de la orden (time in force: GTC, IOC, FOK)","La vigencia de una orden (time in force) es la regla que define cuánto tiempo permanece activa una orden y qué pasa si no se ejecuta completa, con opciones como GTC, IOC y FOK."],["order-book","Libro de órdenes (order book)","El libro de órdenes (order book) es la lista en tiempo real de todas las órdenes de compra (bids) y de venta (asks) pendientes para un par, ordenadas por precio, que muestra a qué precios hay compradores y vendedores y en qué cantidad."],["maker-taker-fees","Comisiones maker y taker","Las comisiones maker y taker son las dos tarifas que cobra un exchange según tu orden añada liquidez al libro de órdenes (maker) o la retire al ejecutarse de inmediato (taker)."]],"lesson":{"id":"E14","slug":"market-limit-cancel","ep":14,"title":"Mercado, límite, cancelar: ¿qué resuelve cada uno?"},"coin":null,"tool":null,"cta":true},"insurance-fund":{"slug":"insurance-fund","cat":"derivatives","en":"Insurance fund","contentLocale":"es","term":"Fondo de seguro","aka":["insurance fund","fondo de garantía","fondo de seguros de futuros"],"short":"El fondo de seguro es una reserva que mantiene un exchange de derivados para cubrir las pérdidas de posiciones liquidadas que no se pudieron cerrar antes de que su margen llegara a cero.","body":[["Cada posición apalancada tiene un precio de quiebra, en el que su margen se agota por completo. La ",["liquidación","liquidation"]," intenta cerrarla antes, cerca del ",["margen de mantenimiento","maintenance-margin"],". Si se cierra a mejor precio que el de quiebra, el sobrante suele ir al fondo de seguro. Si el mercado se mueve tan rápido que se cierra a peor precio, el fondo cubre el déficit."],["Así se evita que las pérdidas de un trader liquidado se repartan entre los ganadores. Cuando el fondo no alcanza, el exchange recurre al ",["desapalancamiento automático (ADL)","auto-deleveraging"],". Por eso el tamaño del fondo es una señal de la solidez del sistema de liquidaciones."],["Muchos exchanges publican el saldo de su fondo de seguro por contrato o por moneda. No es lo mismo que la ",["prueba de reservas","proof-of-reserves"],", que verifica si el exchange tiene los fondos de los clientes. El fondo protege al mercado de futuros, no tus depósitos ante una quiebra del exchange."]],"example":["Un largo de 0,4 ",["BTC","bitcoin"]," tiene precio de quiebra en 47.500 ",["USDT","usdt"],". El motor lo liquida, pero por un movimiento brusco solo consigue cerrarlo a 47.300. El déficit es 0,4 × 200 = 80 USDT, y lo paga el fondo de seguro. En otra liquidación del mismo tamaño, el cierre se hace a 47.700, 200 USDT por encima del precio de quiebra: el sobrante de 80 USDT entra en el fondo."],"mistakes":["Creer que el fondo de seguro protege tus depósitos si el exchange quiebra.","Pensar que el fondo cubre tus propias pérdidas por liquidación; cubre el déficit frente a los demás.","Ignorar el tamaño del fondo al operar contratos poco líquidos en exchanges pequeños."],"faq":[{"q":"¿De dónde sale el dinero del fondo de seguro?","a":"Principalmente del margen sobrante de liquidaciones que se cerraron a mejor precio que el de quiebra, y a veces de aportaciones del propio exchange."},{"q":"¿Qué pasa si el fondo de seguro se queda sin dinero?","a":"El exchange aplica el desapalancamiento automático (ADL) y reduce posiciones ganadoras del lado contrario para cubrir el déficit."}],"title":"¿Qué es el fondo de seguro en futuros cripto?","description":"Qué es el fondo de seguro de un exchange de futuros, cómo se nutre de liquidaciones y qué pasa cuando no alcanza.","related":[["auto-deleveraging","Desapalancamiento automático (ADL)","El desapalancamiento automático o ADL es un mecanismo de último recurso por el que un exchange cierra parte de las posiciones ganadoras de traders del lado opuesto cuando una liquidación no puede cubrirse en el mercado ni con el fondo de seguro."],["liquidation","Liquidación","La liquidación es el cierre forzoso de una posición apalancada por parte del exchange cuando tu margen ya no cubre el margen de mantenimiento exigido."],["proof-of-reserves","Prueba de reservas (PoR)","La prueba de reservas es un método con el que un exchange demuestra que tiene en sus billeteras activos suficientes para cubrir los saldos que sus clientes tienen depositados."],["mark-price","Precio de marca","El precio de marca es un precio de referencia que calculan los exchanges de futuros a partir del índice spot y otros datos, y que usan para calcular la ganancia no realizada y las liquidaciones."]],"lesson":{"id":"E23","slug":"liquidation-mark-price","ep":23,"title":"Liquidación: ¿quién presionó el botón de cierre forzoso?"},"coin":null,"tool":"/liquidations","cta":false},"block-confirmations":{"slug":"block-confirmations","cat":"wallets-security","en":"Block confirmations","contentLocale":"es","term":"Confirmaciones de bloque","aka":["confirmaciones","block confirmations","confirmaciones de red"],"short":"Las confirmaciones de bloque son el número de bloques añadidos a la blockchain desde que se incluyó una transacción, y cuantas más tiene, más difícil es que se revierta.","body":[["Cuando una transacción entra en un bloque, tiene 1 confirmación. Cada bloque nuevo encima suma otra. En redes de ",["prueba de trabajo","proof-of-work"]," como ",["Bitcoin","bitcoin"],", revertir una transacción con varias confirmaciones exigiría rehacer todos esos bloques, algo muy costoso."],"Por eso los exchanges no acreditan un depósito en cuanto aparece en la red: esperan un número mínimo de confirmaciones que fijan para cada moneda y red. Ese requisito suele mostrarse en la página de depósito y puede cambiar con el tiempo.","El tiempo de espera depende del tiempo de bloque. En Bitcoin se produce un bloque cada unos 10 minutos de media, así que varias confirmaciones pueden tardar más de media hora. Las redes con bloques de pocos segundos acumulan confirmaciones mucho más rápido, aunque algunos exchanges esperan la finalidad de la red en lugar de contar bloques."],"example":"Depositas 0,1 BTC en un exchange que, por ejemplo, exige 3 confirmaciones para Bitcoin. Tu transacción entra en un bloque 8 minutos después de enviarla. Si los siguientes bloques llegan a un ritmo medio de 10 minutos, la tercera confirmación llegará unos 20 minutos más tarde, unos 28 minutos en total. En el explorador ves 1/3, luego 2/3 y finalmente 3/3, momento en el que el exchange acredita los 0,1 BTC en tu saldo.","mistakes":["Abrir un ticket de soporte antes de que el depósito alcance las confirmaciones requeridas.","Suponer que todos los exchanges exigen el mismo número de confirmaciones para la misma moneda.","Aceptar un pago grande de un desconocido con 0 confirmaciones."],"faq":[{"q":"¿Cuántas confirmaciones necesita una transacción de Bitcoin?","a":"No hay un número universal. Cada exchange fija el suyo; para montos grandes muchos usuarios esperan 6 confirmaciones como margen de seguridad."},{"q":"¿Por qué mi depósito tiene confirmaciones pero no aparece en el saldo?","a":"Puede faltar alcanzar el mínimo del exchange, o el exchange puede estar procesando con retraso esa red. Revisa la página de depósito y su aviso de estado."}],"title":"¿Qué son las confirmaciones de bloque en cripto?","description":"Qué son las confirmaciones de bloque, por qué los exchanges esperan varias antes de acreditar y cuánto tardan.","related":[["transaction-hash","Hash de transacción (TxID)","Un hash de transacción (TxID) es el identificador único de una transacción en la blockchain, que permite buscarla en un explorador de bloques y comprobar su estado."],["block-explorer","Explorador de bloques","Un explorador de bloques es un sitio o herramienta que te permite buscar y ver en tiempo real las transacciones, direcciones y bloques de una blockchain pública."],["mempool","Mempool","La mempool es la sala de espera de una blockchain: el conjunto de transacciones enviadas que aún no han sido incluidas en un bloque y esperan a ser confirmadas."],["blockchain","Blockchain (cadena de bloques)","Una blockchain o cadena de bloques es un registro digital compartido en el que las transacciones se agrupan en bloques encadenados entre sí, de modo que cambiar un dato antiguo exigiría rehacer todos los bloques posteriores."]],"lesson":{"id":"E10","slug":"transfer-not-arrived","ep":10,"title":"Dice enviado, pero nunca llegó. ¿Dónde debes mirar?"},"coin":null,"tool":null,"cta":false},"impermanent-loss":{"slug":"impermanent-loss","cat":"defi","en":"Impermanent loss","contentLocale":"es","term":"Pérdida impermanente","aka":["impermanent loss","IL","pérdida temporal"],"short":"La pérdida impermanente es la diferencia de valor entre tener tokens depositados en un pool de liquidez y haberlos guardado sin más, causada por un cambio en la relación de precios entre esos tokens.","body":["Cuando el precio de un token del par sube o baja, los arbitrajistas reequilibran el pool y te dejan con más cantidad del token que bajó y menos del que subió. El valor total de tu posición queda por debajo de lo que valdría si hubieras mantenido los tokens fuera.",["Se llama impermanente porque, si los precios vuelven a la relación inicial, la diferencia desaparece. Si retiras la ",["liquidez","liquidity"]," con los precios cambiados, la pérdida se vuelve definitiva."],["En un pool de producto constante, una variación de precio del doble produce una pérdida impermanente de alrededor del 5,7 %; una de cuatro veces, alrededor del 20 %. Las comisiones pueden compensarla o no. Los pools de ",["stablecoins","stablecoin"]," entre sí sufren muy poca, mientras que la liquidez concentrada puede ampliarla si el precio sale de tu rango."]],"example":["Depositas 1 ",["ETH","ethereum"]," y 2.000 ",["USDC","usdc"]," con ETH a 2.000 USDC: 4.000 USDC en total. ETH sube a 8.000 USDC. Por el reequilibrio, tu parte del pool queda en unos 0,5 ETH y 4.000 USDC, que valen 8.000 USDC. Si hubieras guardado 1 ETH y 2.000 USDC, tendrías 10.000 USDC. La diferencia, 2.000 USDC, es una pérdida impermanente del 20 %. Para compensarla necesitarías haber cobrado más de 2.000 USDC en comisiones."],"mistakes":["Pensar que la pérdida impermanente solo ocurre cuando el precio baja; también ocurre cuando sube.","Comparar el resultado del pool con el capital inicial en dólares en lugar de con haber mantenido los tokens.","Asumir que las comisiones siempre compensan la pérdida."],"faq":[{"q":"¿La pérdida impermanente es una pérdida real?","a":"Se convierte en real cuando retiras la liquidez con los precios cambiados. Si los precios vuelven a la relación inicial, desaparece."},{"q":"¿Cómo reducir la pérdida impermanente?","a":"Elegir pares con precios muy correlacionados, como dos stablecoins, y vigilar que las comisiones obtenidas compensen el riesgo."}],"title":"¿Qué es la pérdida impermanente en DeFi?","description":"Qué es la pérdida impermanente, por qué ocurre al aportar liquidez y cómo calcularla con un ejemplo de ETH y USDC.","related":[["liquidity-pool","Pool de liquidez","Un pool de liquidez es un contrato inteligente que guarda reservas de dos o más tokens para que otros usuarios puedan intercambiarlos, a cambio de comisiones que reciben quienes aportaron esos fondos."],["amm","Creador de mercado automatizado (AMM)","Un creador de mercado automatizado (AMM) es un contrato inteligente que fija el precio de un intercambio con una fórmula basada en las reservas de un pool de liquidez, en lugar de emparejar órdenes de compradores y vendedores."],["yield-farming","Yield farming (agricultura de rendimiento)","El yield farming es la práctica de mover cripto entre protocolos DeFi, aportando liquidez, prestando o depositando tokens, para obtener rendimientos en forma de comisiones, intereses y recompensas en tokens."],["apr-vs-apy","APR vs APY","APR es la tasa de rendimiento anual simple, sin reinvertir las ganancias, y APY es el rendimiento anual efectivo que incluye el efecto del interés compuesto al reinvertirlas."]],"lesson":null,"coin":{"slug":"uniswap","name":"Uniswap","symbol":"UNI"},"tool":null,"cta":false},"liquid-staking":{"slug":"liquid-staking","cat":"defi","en":"Liquid staking","contentLocale":"es","term":"Staking líquido","aka":["liquid staking","LST","token de staking líquido"],"short":"El staking líquido es una forma de hacer staking en la que recibes un token que representa tus fondos bloqueados más sus recompensas, y que puedes seguir usando o vender mientras tanto.","body":[["Por ejemplo, al depositar ",["ETH","ethereum"]," en Lido recibes stETH; en otros protocolos recibes tokens como rETH o cbETH. Estos tokens, llamados LST, acumulan las recompensas de ",["staking","staking"],", ya sea aumentando tu saldo o subiendo su valor frente a ETH."],["La ventaja es la ",["liquidez","liquidity"],": no tienes que esperar el ",["desbloqueo","token-unlock"]," de la red para salir, porque puedes vender el LST en una ",["DEX","dex"],", y además puedes usarlo como garantía en protocolos de préstamo o aportarlo a pools."],["Los riesgos son varios: un fallo en el contrato del protocolo, la concentración de mucho stake en pocos operadores y el riesgo de que el LST cotice por debajo del activo subyacente en momentos de tensión, lo que se conoce como ",["depeg","depeg"],". Si usas el LST como garantía en un préstamo, ese descuento puede provocar liquidaciones."]],"example":"Depositas 5 ETH en un protocolo de staking líquido y recibes 5 stETH. Con una recompensa que ronda el 3 % anual, al cabo de un año tendrías unos 5,15 stETH. Mientras tanto, depositas los stETH como garantía para pedir prestados 4.000 USDC. Si en un momento de pánico stETH cae a 0,95 ETH en el mercado, tu garantía vale un 5 % menos, y tu préstamo se acerca al umbral de liquidación aunque el precio de ETH no se haya movido.","mistakes":["Pensar que 1 LST siempre vale exactamente 1 ETH en el mercado secundario.","Apalancarse con LST como garantía sin margen frente a un posible descuento.","Ignorar las comisiones que cobra el protocolo sobre las recompensas."],"faq":[{"q":"¿Qué diferencia hay entre staking y staking líquido?","a":"En el staking normal tus tokens quedan bloqueados. En el staking líquido recibes un token que representa esa posición y puedes usarlo o venderlo."},{"q":"¿stETH es lo mismo que ETH?","a":"No. Es un token que representa ETH en staking en Lido y suele cotizar cerca de ETH, pero su precio de mercado puede desviarse."}],"title":"¿Qué es el staking líquido (liquid staking)?","description":"Qué es el staking líquido, cómo funcionan tokens como stETH y qué riesgos tiene usarlos en DeFi o como garantía.","related":[["staking","Staking","El staking consiste en bloquear criptomonedas de una red de prueba de participación para ayudar a validar bloques, a cambio de recompensas pagadas en esa misma moneda."],["restaking","Restaking","El restaking es la reutilización de ETH ya puesto en staking, o de sus tokens de staking líquido, para asegurar servicios adicionales a cambio de recompensas extra y de un riesgo adicional de penalización."],["wrapped-token","Token envuelto (wrapped token)","Un token envuelto es un token que representa otro activo en una blockchain distinta o en otro estándar, respaldado uno a uno por el activo original que queda bloqueado o custodiado."],["depeg","Depeg (pérdida de paridad)","Un depeg es cuando una stablecoin u otro activo vinculado pierde su paridad y cotiza claramente por encima o por debajo del valor que debería mantener, por ejemplo 1 dólar."]],"lesson":null,"coin":{"slug":"lido-dao","name":"Lido DAO","symbol":"LDO"},"tool":null,"cta":false},"restaking":{"slug":"restaking","cat":"defi","en":"Restaking","contentLocale":"es","term":"Restaking","aka":["re-staking","restakear","LRT"],"short":"El restaking es la reutilización de ETH ya puesto en staking, o de sus tokens de staking líquido, para asegurar servicios adicionales a cambio de recompensas extra y de un riesgo adicional de penalización.","body":[["EigenLayer popularizó el modelo en ",["Ethereum","ethereum"],". Los usuarios aceptan que su ETH en ",["staking","staking"]," respalde también otros servicios, como oráculos, puentes o capas de disponibilidad de datos. Si los operadores cumplen, reciben recompensas extra; si fallan las reglas de esos servicios, el stake puede ser penalizado."],["Existen protocolos de restaking líquido que entregan un token, llamado LRT, a cambio del depósito. Ese token puede usarse en ",["DeFi","defi"],", igual que un ",["LST","liquid-staking"],", pero acumula más capas de riesgo: el de la red, el del protocolo de staking líquido, el del protocolo de restaking y el de cada servicio asegurado."],["Muchas campañas de restaking se apoyaron en puntos o ",["airdrops","airdrop"]," esperados, no solo en rendimientos actuales. Antes de entrar conviene entender qué recompensas son reales hoy, qué penalizaciones existen y cuánto tarda salir."]],"example":"Tienes 4 ETH en staking con un rendimiento de alrededor del 3 % anual. Los depositas en un protocolo de restaking que añade, por ejemplo, un 1,5 % anual adicional de los servicios asegurados. En un año podrías pasar de 4 ETH a unos 4,18 ETH, frente a 4,12 ETH solo con staking. Pero si un operador recibe una penalización del 2 %, perderías 0,08 ETH, más que toda la ganancia extra de 0,06 ETH.","mistakes":["Considerar el restaking como staking normal con más rendimiento y sin riesgo extra.","Entrar solo por puntos o airdrops esperados sin valorar las condiciones de salida.","Usar un LRT como garantía sin tener en cuenta que puede perder su paridad."],"faq":[{"q":"¿Qué es un LRT?","a":"Un token de restaking líquido que representa ETH o LST depositados en un protocolo de restaking y que puede usarse en DeFi."},{"q":"¿El restaking aumenta el riesgo?","a":"Sí. Suma riesgos de contratos y de penalizaciones adicionales encima del staking normal."}],"title":"¿Qué es el restaking en Ethereum?","description":"Qué es el restaking, cómo funciona con EigenLayer y tokens LRT y qué riesgos añade frente al staking tradicional.","related":[["liquid-staking","Staking líquido","El staking líquido es una forma de hacer staking en la que recibes un token que representa tus fondos bloqueados más sus recompensas, y que puedes seguir usando o vender mientras tanto."],["staking","Staking","El staking consiste en bloquear criptomonedas de una red de prueba de participación para ayudar a validar bloques, a cambio de recompensas pagadas en esa misma moneda."],["validator","Validador (validator)","Un validador es un participante de una blockchain de prueba de participación que bloquea monedas como garantía y ejecuta software para proponer bloques y votar sobre su validez a cambio de recompensas."],["smart-contract","Contrato inteligente (smart contract)","Un contrato inteligente (smart contract) es un programa publicado en una blockchain que se ejecuta automáticamente según reglas predefinidas cuando alguien interactúa con él, sin que un intermediario tenga que aprobarlo."]],"lesson":null,"coin":{"slug":"ethereum","name":"Ethereum","symbol":"ETH"},"tool":null,"cta":false},"defi-lending":{"slug":"defi-lending","cat":"defi","en":"DeFi lending","contentLocale":"es","term":"Préstamos DeFi","aka":["DeFi lending","préstamos descentralizados","lending DeFi","protocolo de préstamos"],"short":"Los préstamos DeFi son protocolos en los que depositas cripto para ganar intereses o la usas como garantía para pedir prestados otros tokens, con reglas aplicadas automáticamente por contratos inteligentes.","body":["En protocolos como Aave o Compound, los prestamistas depositan tokens en un mercado común y reciben un interés variable. Los prestatarios aportan garantía y piden prestado otro activo. El tipo de interés sube cuando se usa mucho del dinero disponible y baja cuando se usa poco.",["Casi todos los préstamos están sobrecolateralizados: debes aportar más valor en garantía del que pides. Cada activo tiene un ratio máximo de préstamo y un umbral de ",["liquidación","liquidation"],", y los oráculos informan del precio de forma continua."],["Si el valor de tu garantía cae y tu factor de salud baja de 1, cualquier liquidador puede pagar parte de tu deuda y quedarse con parte de tu garantía con un descuento, que es la penalización por liquidación. No hay ",["margin call","margin-call"]," con espera: ocurre automáticamente."]],"example":["Depositas 2 ",["ETH","ethereum"]," como garantía con ETH a 3.000 ",["USDC","usdc"],", es decir 6.000 USDC, en un mercado con umbral de liquidación del 80 %. Pides prestados 3.000 USDC. Tu límite antes de liquidación es 6.000 por 0,80, es decir 4.800 USDC, y tu factor de salud es 4.800 entre 3.000, igual a 1,6. Si ETH cae a 1.875 USDC, tu garantía vale 3.750 USDC, el límite baja a 3.000 USDC y el factor de salud llega a 1: tu posición puede ser liquidada."],"mistakes":["Pedir prestado cerca del máximo permitido sin margen ante caídas de precio.","No vigilar el factor de salud en momentos de alta volatilidad.","Olvidar que los intereses del préstamo son variables y aumentan la deuda con el tiempo."],"faq":[{"q":"¿Por qué los préstamos DeFi piden más garantía que el préstamo?","a":"Porque no hay verificación de identidad ni cobro judicial. La sobrecolateralización protege a los prestamistas si el precio de la garantía cae."},{"q":"¿Qué pasa si me liquidan en un protocolo DeFi?","a":"Un liquidador paga parte de tu deuda y se queda con parte de tu garantía con descuento. Conservas el resto de la garantía y la deuda restante."}],"title":"¿Qué son los préstamos DeFi y cómo funcionan?","description":"Cómo funcionan los préstamos DeFi, qué es el factor de salud y cuándo se liquida tu garantía en protocolos como Aave.","related":[["defi","DeFi (finanzas descentralizadas)","DeFi, o finanzas descentralizadas, es el conjunto de servicios financieros, como intercambios, préstamos o rendimientos, que funcionan mediante contratos inteligentes en una blockchain sin un intermediario central."],["liquidation","Liquidación","La liquidación es el cierre forzoso de una posición apalancada por parte del exchange cuando tu margen ya no cubre el margen de mantenimiento exigido."],["oracle","Oráculo blockchain","Un oráculo blockchain es un servicio que lleva datos externos, como el precio de un activo, a los contratos inteligentes, que por sí solos no pueden consultar información fuera de la cadena."],["crypto-backed-stablecoin","Stablecoin respaldada por criptomonedas","Una stablecoin respaldada por criptomonedas es una moneda estable que se emite depositando otras criptomonedas como colateral, normalmente por un valor mayor al de las monedas creadas."],["flash-loan","Préstamo flash (flash loan)","Un préstamo flash (flash loan) es un préstamo sin garantía que debe pedirse y devolverse dentro de la misma transacción de blockchain; si no se devuelve, toda la transacción se revierte como si nunca hubiera ocurrido."]],"lesson":null,"coin":{"slug":"aave","name":"Aave","symbol":"AAVE"},"tool":null,"cta":false},"cbdc":{"slug":"cbdc","cat":"stablecoins","en":"CBDC (central bank digital currency)","contentLocale":"es","term":"CBDC (moneda digital de banco central)","aka":["CBDC","moneda digital de banco central","euro digital"],"short":"Una CBDC es una moneda digital emitida directamente por un banco central, que representa dinero oficial del país en forma electrónica y tiene el mismo valor que el efectivo.","body":[["A diferencia de una ",["stablecoin","stablecoin"],", la CBDC no la emite una empresa privada sino la autoridad monetaria. Es dinero de curso legal, no un token que promete reembolso. Puede usarse para pagos minoristas entre personas y comercios o solo entre bancos, en la llamada CBDC mayorista."],["No es lo mismo que una ",["criptomoneda","cryptocurrency"]," como ",["bitcoin","bitcoin"],". Una CBDC está centralizada: el banco central controla la emisión y las reglas, y el sistema puede incluir límites de saldo, identificación del usuario y diferentes niveles de privacidad según el diseño de cada país."],"Varios países han lanzado o probado CBDC, como el e-CNY de China o el eNaira de Nigeria, y el Banco Central Europeo trabaja en un euro digital. Los diseños, plazos y reglas varían mucho por jurisdicción."],"example":"Supón que un país lanza una CBDC minorista con un límite de saldo de 3.000 unidades por persona. Recibes tu salario de 2.500 unidades en tu cuenta bancaria y pasas 500 a tu monedero de CBDC para pagos diarios. Pagas un café de 3 unidades en una tienda y la transferencia se liquida al instante. Si intentas mover 4.000 unidades al monedero, el sistema rechazaría 1.000 por superar el límite fijado por el banco central.","mistakes":["Confundir una CBDC con una criptomoneda descentralizada.","Pensar que una CBDC es una stablecoin privada como USDT o USDC.","Suponer que todas las CBDC tienen las mismas reglas de privacidad y límites."],"faq":[{"q":"¿Una CBDC es una criptomoneda?","a":"No. Usa tecnología digital y a veces registros distribuidos, pero la emite y controla un banco central. No es descentralizada ni tiene un suministro fijo."},{"q":"¿Qué diferencia hay entre una CBDC y una stablecoin?","a":"La CBDC es dinero oficial emitido por el banco central. Una stablecoin la emite una empresa o un protocolo y su valor depende de sus reservas o de su mecanismo."}],"title":"¿Qué es una CBDC? Moneda digital de banco central","description":"Qué es una CBDC, en qué se diferencia de una stablecoin y de bitcoin, y qué tipos de monedas digitales de banco central existen.","related":[["stablecoin","Stablecoin (moneda estable)","Una stablecoin es una criptomoneda diseñada para mantener un valor estable frente a un activo de referencia, normalmente el dólar estadounidense, gracias a reservas, garantías en cripto u otros mecanismos."],["fiat-on-ramp","Rampa de entrada fiat (on-ramp)","Una rampa de entrada fiat es cualquier servicio que te permite convertir dinero tradicional, como pesos, euros o dólares, en criptomonedas, por ejemplo con transferencia bancaria, tarjeta o P2P."],["kyc","KYC (conoce a tu cliente)","El KYC es el proceso de verificación de identidad que exigen los exchanges y otros servicios regulados para confirmar quién eres antes de dejarte operar o retirar fondos."],["blockchain","Blockchain (cadena de bloques)","Una blockchain o cadena de bloques es un registro digital compartido en el que las transacciones se agrupan en bloques encadenados entre sí, de modo que cambiar un dato antiguo exigiría rehacer todos los bloques posteriores."]],"lesson":{"id":"E02","slug":"is-usdt-a-dollar","ep":2,"title":"¿Es USDT un dólar? ¿Por qué se usa tanto al comprar cripto?"},"coin":null,"tool":null,"cta":false},"node":{"slug":"node","cat":"onchain","en":"Node","contentLocale":"es","term":"Nodo","aka":["nodo de blockchain","full node","nodo completo"],"short":"Un nodo es un ordenador que ejecuta el software de una blockchain, guarda una copia de su registro y verifica y retransmite transacciones y bloques según las reglas de la red.","body":[["Una ",["blockchain","blockchain"]," no vive en un servidor central, sino en miles de nodos repartidos por el mundo. Cada nodo completo descarga el historial, comprueba que cada transacción y cada bloque cumplen las reglas y rechaza lo que no las cumple. Así nadie puede cambiar las reglas por su cuenta."],"Hay varios tipos. Los nodos completos verifican todo; los nodos ligeros solo consultan lo necesario y confían en otros; los nodos de archivo guardan todo el estado histórico. Los mineros y los validadores también ejecutan nodos, pero además producen bloques.",["Para ti, la diferencia práctica es de confianza. Si usas un monedero que se conecta al nodo de una empresa, confías en esa empresa para ver tu saldo. Ejecutar tu propio nodo de ",["Bitcoin","bitcoin"]," te permite verificar tus transacciones sin depender de terceros, a cambio de espacio en disco y conexión estable."]],"example":["Supón que quieres montar un nodo completo de Bitcoin en casa. Necesitas un disco con espacio de sobra para la cadena, que ya ocupa varios cientos de gigabytes, y una conexión que puede transferir decenas de gigabytes al mes. Si tu disco es de 1 TB y la cadena ocupa 650 GB, te quedan 350 GB de margen. Una vez sincronizado, tu monedero puede consultar tu propio nodo y verificar que un pago de 0,02 BTC tiene ",["confirmaciones","block-confirmations"]," reales."],"mistakes":["Confundir un nodo con un minero: todos los mineros usan nodos, pero no todos los nodos minan.","Pensar que ejecutar un nodo de Bitcoin genera recompensas automáticas.","Conectar el monedero a nodos públicos desconocidos sin entender que ven tus direcciones."],"faq":[{"q":"¿Ejecutar un nodo da dinero?","a":"Un nodo completo de Bitcoin no recibe recompensas. En redes de prueba de participación, solo los nodos validadores con fondos en staking reciben recompensas."},{"q":"¿Qué diferencia hay entre un nodo y un validador?","a":"Un nodo verifica y retransmite datos. Un validador es un nodo que además propone y firma bloques en una red de prueba de participación."}],"title":"¿Qué es un nodo en blockchain? Tipos y función","description":"Qué es un nodo de blockchain, qué hace un nodo completo frente a uno ligero y por qué importa para la descentralización.","related":[["blockchain","Blockchain (cadena de bloques)","Una blockchain o cadena de bloques es un registro digital compartido en el que las transacciones se agrupan en bloques encadenados entre sí, de modo que cambiar un dato antiguo exigiría rehacer todos los bloques posteriores."],["validator","Validador (validator)","Un validador es un participante de una blockchain de prueba de participación que bloquea monedas como garantía y ejecuta software para proponer bloques y votar sobre su validez a cambio de recompensas."],["mining","Minería de criptomonedas","La minería de criptomonedas es el proceso por el que equipos especializados aportan potencia de cálculo a una red de prueba de trabajo para validar transacciones, crear nuevos bloques y cobrar la recompensa en monedas nuevas y comisiones."],["mempool","Mempool","La mempool es la sala de espera de una blockchain: el conjunto de transacciones enviadas que aún no han sido incluidas en un bloque y esperan a ser confirmadas."]],"lesson":null,"coin":{"slug":"bitcoin","name":"Bitcoin","symbol":"BTC"},"tool":null,"cta":false},"aml":{"slug":"aml","cat":"regulation","en":"AML (anti-money laundering)","contentLocale":"es","term":"AML (prevención del lavado de dinero)","aka":["AML","antilavado","prevención de blanqueo de capitales","PLD"],"short":"AML es el conjunto de leyes, controles y procesos que usan los exchanges y otras entidades financieras para detectar y prevenir el lavado de dinero y la financiación del terrorismo.","body":[["Las siglas vienen del inglés anti-money laundering. En cripto incluye el ",["KYC","kyc"],", el análisis de transacciones en la ",["blockchain","blockchain"],", la vigilancia de operaciones inusuales y la comunicación de operaciones sospechosas a las autoridades financieras de cada país."],["Los exchanges usan herramientas de ",["análisis on-chain","on-chain-analysis"]," para puntuar el riesgo de las direcciones. Si un depósito viene de una dirección asociada a un hackeo, un mezclador o un mercado ilegal, el exchange puede congelar los fondos y pedirte explicaciones."],"Para un usuario honesto, AML se nota sobre todo en preguntas sobre el origen de los fondos, en revisiones de retiros grandes y en bloqueos temporales. Responder con documentos claros suele resolverlo. Las exigencias concretas cambian según la jurisdicción."],"example":["Supón que vendes un coche por 12.000 USD, compras ",["USDT","usdt"]," en ",["P2P","p2p-trading"]," y lo depositas en un exchange. El sistema AML detecta que el depósito es mucho mayor que tu actividad habitual de unos 300 USD al mes y bloquea el retiro. Te pide justificar el origen. Subes el contrato de compraventa y el comprobante bancario del pago recibido. Tras la revisión, el exchange libera la cuenta y puedes retirar con normalidad."],"mistakes":["Aceptar fondos de desconocidos en tu cuenta sin saber de dónde vienen.","Fraccionar depósitos para no superar umbrales, algo que los sistemas AML detectan y consideran sospechoso.","No guardar comprobantes del origen de tus fondos para posibles revisiones."],"faq":[{"q":"¿Por qué el exchange congeló mi retiro por AML?","a":"Puede ser por un monto inusual, una dirección de riesgo o datos incompletos. Normalmente se resuelve aportando la documentación que te solicitan."},{"q":"¿Qué diferencia hay entre KYC y AML?","a":"El KYC verifica quién eres. AML es el marco más amplio que usa esa información, junto con el análisis de transacciones, para prevenir el lavado de dinero."}],"title":"¿Qué es AML en cripto? Prevención de lavado","description":"Qué significa AML en los exchanges cripto, cómo funcionan los controles antilavado y por qué pueden congelar un retiro.","related":[["kyc","KYC (conoce a tu cliente)","El KYC es el proceso de verificación de identidad que exigen los exchanges y otros servicios regulados para confirmar quién eres antes de dejarte operar o retirar fondos."],["travel-rule","Regla de viaje (Travel Rule)","La regla de viaje es una norma internacional contra el lavado de dinero que obliga a los proveedores de criptoactivos a enviar y recibir los datos del remitente y del beneficiario en las transferencias."],["vasp","VASP (proveedor de servicios de activos virtuales)","Un VASP es una empresa que presta servicios con criptoactivos para terceros, como cambio, custodia o transferencias, y por eso está sujeta a normas de registro, KYC y prevención del lavado."],["p2p-trading","Trading P2P (C2C)","El trading P2P es la compraventa directa de criptomonedas entre usuarios, donde pagas con transferencia u otros métodos locales y el exchange retiene la cripto en garantía hasta que se confirma el pago."]],"lesson":{"id":"E05","slug":"kyc-who-gets-your-id","ep":5,"title":"¿Cómo funciona el KYC y a quién debes darle tu documento?"},"coin":null,"tool":null,"cta":false},"tokenized-gold":{"slug":"tokenized-gold","cat":"tokenized-assets","en":"Tokenized gold","contentLocale":"es","term":"Oro tokenizado","aka":["oro tokenizado","tokenized gold","oro digital"],"short":"El oro tokenizado es un token en una blockchain respaldado por oro físico guardado en bóvedas, donde cada token representa una cantidad concreta de oro, normalmente una onza troy o un gramo.","body":["El emisor compra oro físico, lo almacena con un custodio y emite tokens equivalentes. PAX Gold (PAXG), de Paxos, y Tether Gold (XAUT) son dos ejemplos conocidos, donde cada token representa una onza troy fina de oro. El precio del token sigue al del oro.",["La ventaja frente al oro físico es que puedes comprar fracciones pequeñas, transferirlas en minutos y usarlas en exchanges o en ",["DeFi","defi"],". Frente a un ETF de oro, el token se puede guardar en tu propio monedero y mover las 24 horas."],"El riesgo está en la confianza en el emisor y el custodio: que el oro exista, esté auditado y que puedas canjearlo si lo deseas. Las condiciones de canje en oro físico o en efectivo, sus mínimos y comisiones dependen de cada emisor."],"example":["Supón que la onza de oro cotiza a 2.400 USD y compras 0,25 tokens de oro tokenizado que representa una onza por token, pagando 600 ",["USDT","usdt"],". Si el oro sube un 5 %, a 2.520 USD, tus tokens valen 630 USDT. Si quieres enviarlos a otro monedero, pagas la ",["comisión de gas","gas-fee"]," de la red, no un coste de transporte físico. Si el token cotiza en un exchange a 2.390 mientras el oro está a 2.400, compras con un pequeño descuento del 0,4 %."],"mistakes":["No comprobar si el emisor publica auditorías o informes de las reservas de oro.","Suponer que siempre puedes canjear pequeñas cantidades por oro físico.","Olvidar que el precio sigue al oro, no al dólar, y por tanto también puede bajar."],"faq":[{"q":"¿El oro tokenizado está respaldado por oro real?","a":"Los productos serios están respaldados por oro físico en bóvedas y publican informes o auditorías. Revisa siempre la documentación del emisor."},{"q":"¿Qué diferencia hay entre PAXG y XAUT?","a":"Ambos representan una onza troy de oro, pero los emiten empresas distintas, Paxos y Tether, con custodios, reglas de canje y redes diferentes."}],"title":"¿Qué es el oro tokenizado? PAXG, XAUT y más","description":"Qué es el oro tokenizado, cómo se respalda con oro físico y qué diferencias hay con el oro en bóveda y con un ETF de oro.","related":[["real-world-assets","Activos del mundo real (RWA)","Los activos del mundo real (RWA) son activos tradicionales, como bonos, inmuebles, oro, acciones o créditos, que se representan como tokens en una blockchain para poder transferirse y usarse on-chain."],["stablecoin","Stablecoin (moneda estable)","Una stablecoin es una criptomoneda diseñada para mantener un valor estable frente a un activo de referencia, normalmente el dólar estadounidense, gracias a reservas, garantías en cripto u otros mecanismos."],["custodial-wallet","Billetera custodial","Una billetera custodial es una billetera en la que un tercero, normalmente un exchange o una empresa, guarda las claves privadas y controla los fondos en nombre del usuario."],["tokenized-stocks","Acciones tokenizadas","Las acciones tokenizadas son tokens en una blockchain que representan acciones de empresas cotizadas y siguen su precio, normalmente respaldadas por acciones reales que guarda un custodio."]],"lesson":null,"coin":{"slug":"pax-gold","name":"PAX Gold","symbol":"PAXG"},"tool":"/topics/tokenized-assets","cta":false}});
